"""Selective Compulsory Volume 2, Chapters 3–5; Selective Compulsory Volume 3, Chapter 1 (draft; People's Education Press, 2019)."""
from phy_hs_lib import T, C, N

# ---------------- Selective Compulsory Volume 2, Chapter 3: Alternating Current
T("ac_generate", "Motion and Interaction", "conceptual",
  "A rectangular coil rotating uniformly about an axis perpendicular to a uniform magnetic field generates a sinusoidal induced emf. Learn the properties of the neutral plane, the instantaneous emf e = Em sinωt when timing begins at the neutral plane, and the peak value Em = NBSω.",
  ["Describe the magnetic flux, induced emf, and current direction at the neutral plane", "Write e = Em sinωt for timing from the neutral plane and calculate instantaneous values", "Use Em = NBSω to calculate the peak value and analyze the effects of changing rotation speed"],
  [("S2.2.4", "exact"), ("S2.2.2", "inferred")],
  pre=[("faraday", "hard"), ("flux", "hard"), ("emf_cutting", "soft"), ("J:induction", "soft")],
  math=[("cnm_h076", "e = Em sin(ωt) is a sinusoidal function; Em is the amplitude, and ω determines the period.")],
  qs=[
    C("basic", "A rectangular coil rotates uniformly in a uniform magnetic field about an axis perpendicular to the field. When the coil reaches the neutral plane (its plane is perpendicular to the field), which statement is correct?",
      "Magnetic flux is maximum, induced emf is zero, and the current reverses direction at this position",
      ["Magnetic flux and induced emf are both maximum, and the current direction does not change",
       "Magnetic flux is zero, induced emf is maximum, and the current reverses direction at this position",
       "Magnetic flux and induced emf are both zero, and the current direction does not change"],
      "At the neutral plane, the coil's plane is perpendicular to the magnetic field, so magnetic flux is maximum. The coil sides move parallel to the field lines and do not cut them, so the rate of change of Φ is zero and e = 0. The current reverses each time the coil passes through the neutral plane. Maximum flux coincides with zero emf; do not confuse the two."),
    N("basic", "A coil starts timing from the neutral plane and generates an induced emf e = Em sinωt, where Em = 20 V and ω = 100π rad/s. What is the instantaneous emf e at t = 1/600 s, in V? (Enter a number only.)",
      "10",
      "ωt = 100π × (1/600) = π/6, so e = 20 × sin(π/6) = 20 × 0.5 = 10 V. Using cos by mistake gives 17.3 V.",
      "round(20*sin(100*pi*(1/600)),6)"),
    N("standard", "A rectangular coil has N = 50 turns and area S = 0.01 m². It rotates uniformly at ω = 100 rad/s about an axis perpendicular to a uniform magnetic field of B = 0.4 T. Find the peak induced emf Em in V. (Enter a number only.)",
      "20",
      "Em = NBSω = 50 × 0.4 × 0.01 × 100 = 20 V. Omitting the number of turns N gives 0.4 V.",
      "round(50*0.4*0.01*100,6)"),
    C("advanced", "All other conditions remain the same, but the rotation speed of a rectangular coil in a uniform magnetic field is doubled. How do the peak emf Em and period T of the sinusoidal alternating emf change?",
      "Em doubles and T is halved",
      ["Em is unchanged and T is halved",
       "Em doubles and T is unchanged",
       "Em quadruples and T is halved"],
      "Em = NBSω and ω = 2πn, so doubling the rotation speed doubles ω and Em. Since T = 2π/ω, the period is halved. Em is proportional to ω, not to its square."),
  ])

T("ac_describe", "Energy", "procedural",
  "Describe alternating current using its period, frequency, peak value, and RMS value. The RMS value is the DC value with the same heating effect. For sinusoidal AC, E = Em/√2; for nonsinusoidal AC, calculate RMS from the heating effect over one period rather than using the average value.",
  ["Read the peak value, period, and frequency from e = Em sinωt", "Know the √2 relationship between the RMS and peak values of sinusoidal AC", "Calculate RMS values of nonsinusoidal AC from its heating effect"],
  [("S2.2.4", "exact")],
  pre=[("ac_generate", "hard"), ("joule", "hard"), ("electric_work", "soft")],
  math=[("cnm_h066", "Use the period and graph of a sine function to read the period and peak value of an alternating current.")],
  qs=[
    C("basic", "A sinusoidal alternating emf has the instantaneous value e = 10√2 sin(100πt) V. What is its RMS value?",
      "10 V", ["10√2 V", "5√2 V", "20 V"],
      "For sinusoidal alternating current, E = Em/√2 = 10√2/√2 = 10 V. 10√2 V is the peak value; 5√2 V results from incorrectly dividing the peak value by 2.",
      verify="round(10*sqrt(2)/sqrt(2),6)"),
    N("basic", "A sinusoidal alternating emf is e = 311 sin(100πt) V. What is its frequency in Hz? (Enter a number only.)", "50",
      "ω = 2πf = 100π rad/s, so f = 50 Hz and the period T = 0.02 s. Treating 100π directly as the frequency gives 100π Hz.",
      "round(100*pi/(2*pi),6)"),
    N("standard", "During the first half of a period, an alternating current is constantly 1 A; during the second half, it is constantly −7 A in the opposite direction. Find its RMS value in A. (Enter a number only.)",
      "5",
      "From the heating effect, I²RT = (1² R T/2) + (7² R T/2), so I² = (1 + 49)/2 = 25 and I = 5 A. The average absolute value is 4 A and the signed average is −3 A; neither is the RMS value.",
      "sqrt((1**2+7**2)/2)"),
    C("standard", "Household mains voltage is 220 V at 50 Hz. What minimum voltage rating must a capacitor connected to this circuit have to avoid dielectric breakdown?",
      "About 311 V", ["220 V", "About 156 V", "About 440 V"],
      "220 V is the RMS value, and the peak value is Um = 220√2 ≈ 311 V. Breakdown depends on the maximum voltage, so the capacitor's rating must exceed the peak; using 220 V would incorrectly suggest that a 220 V rating is sufficient."),
  ])

T("transformer", "Energy", "conceptual",
  "A transformer uses mutual induction to change AC voltage. An ideal transformer has no energy losses: the primary-to-secondary voltage ratio equals the turns ratio, current is inversely proportional to the turns ratio, and input power equals output power. A transformer cannot change DC voltage or the frequency of AC.",
  ["Use U1/U2 = n1/n2 and I1/I2 = n2/n1 in calculations", "Know that transformers operate only with alternating current and do not change frequency or power", "Analyze how changes in the load affect quantities in the primary and secondary coils"],
  [("S2.2.5", "exact"), ("S2.2.3", "inferred")],
  pre=[("ac_describe", "hard"), ("faraday", "hard"), ("self_inductance", "soft")],
  qs=[
    N("basic", "An ideal transformer has n1 = 1100 primary turns and n2 = 60 secondary turns. The primary is connected to a 220 V AC supply. Find the secondary voltage in V. (Enter a number only.)",
      "12",
      "U1/U2 = n1/n2, so U2 = U1 n2/n1 = 220 × 60/1100 = 12 V. Reversing the turns ratio gives 4033 V.",
      "round(220*60/1100,6)"),
    C("basic", "The primary of an ideal transformer is connected to a steady DC source. Once the circuit is stable, what is the voltage across the secondary?",
      "Zero, because a transformer cannot change DC voltage",
      ["A steady voltage transformed according to the turns ratio", "A steady voltage equal to that across the primary", "An alternating voltage transformed according to the turns ratio"],
      "A transformer produces an induced emf in the secondary only when changing current in the primary creates changing magnetic flux. DC produces a constant magnetic field and constant flux in the core, so no emf is induced in the secondary."),
    N("standard", "An ideal transformer has a primary-to-secondary turns ratio n1:n2 = 10:1. The primary is connected to a 220 V AC supply, and the secondary is connected to a load resistor R = 11 Ω. Find the primary current I1 in A. (Enter a number only.)",
      "0.2",
      "U2 = U1/10 = 22 V and I2 = U2/R = 2 A. Since I1/I2 = n2/n1 = 1/10, I1 = 0.2 A. Alternatively, P_in = P_out gives 220 I1 = 22 × 2, so I1 = 0.2 A. Using I1/I2 = n1/n2 by mistake gives 20 A.",
      "round(220/10/11/10,6)"),
    C("standard", "The primary of an ideal transformer is connected to an AC source with constant voltage, and the secondary is connected to a load resistor. If the load resistance decreases, which statement is correct?",
      "The secondary voltage is unchanged, the secondary current increases, and the primary current increases",
      ["The secondary voltage decreases, the secondary current increases, and the primary current increases",
       "The secondary voltage is unchanged, the secondary current increases, and the primary current is unchanged",
       "The secondary voltage is unchanged, the secondary current decreases, and the primary current decreases"],
      "U2 = U1 n2/n1 is determined by the primary voltage and turns ratio, so it does not depend on the load. When R decreases, I2 = U2/R and output power increase. Input power equals output power, so I1 also increases."),
  ])

T("exp_transformer", "Interdisciplinary Practice", "procedural",
  "Use a disassemblable transformer, low-voltage AC source, and AC voltmeter to investigate how primary and secondary voltages depend on the numbers of turns. Vary the turns one at a time using controlled variables, record the voltages, compare voltage and turns ratios, and analyze experimental error.",
  ["Explain why the experiment uses a low-voltage AC source and an AC voltmeter", "Design the experiment and process the data using controlled variables", "Analyze why the measured voltage ratio differs from the turns ratio"],
  [("S2.X.2", "exact"), ("S2.2.5", "inferred")],
  pre=[("transformer", "hard"), ("exp_multimeter", "soft"), ("ac_describe", "soft")],
  qs=[
    C("basic", "When investigating the relationship between primary and secondary voltage and the number of turns, what should be connected to the primary?",
      "A low-voltage AC source (no more than 12 V)",
      ["A low-voltage DC source, such as a battery", "A 220 V AC supply connected directly", "A high-voltage DC source"],
      "Transformers change AC voltage only, so the source must provide AC. For safety, use the low-voltage AC output of a student power supply, generally no more than 12 V; do not connect directly to 220 V mains."),
    C("basic", "An experiment keeps the primary turns and voltage constant while varying the secondary turns to study how secondary voltage depends on the number of turns. Which method is being used?",
      "Controlled-variable method", ["Equivalent substitution", "Idealized modeling", "Infinitesimal method"],
      "Changing one variable at a time while keeping all others constant is the controlled-variable method."),
    N("standard", "In an experiment, the primary has n1 = 400 turns and voltage U1 = 2.0 V; the secondary has n2 = 800 turns and measured voltage U2 = 3.8 V. The theoretical secondary voltage is U2 = n2U1/n1 = 4.0 V. By what percentage is the measured value below the theoretical value? (Enter a number without the percent sign.)",
      "5",
      "Percentage below the theoretical value = (4.0 - 3.8)/4.0 × 100% = 5%. Use the theoretical value as the denominator; using the measured value gives about 5.3%.",
      "round((4.0-3.8)/4.0*100,6)", percent=True),
    C("advanced", "In an experiment, the measured secondary voltage is consistently a little less than (n2/n1)U1. What is the main reason?",
      "Some magnetic flux misses the core, and the coils and core heat up, dissipating energy",
      ["The AC direction changes periodically, so the secondary current partially cancels itself",
       "The AC voltage range of a multimeter measures the average value, so the reading is low",
       "When the secondary has more turns than the primary, the voltage ratio does not equal the turns ratio"],
      "A real transformer is not ideal: not all magnetic flux links the secondary (leakage flux), the wires have resistance and heat up, and eddy currents cause losses in the core. Therefore the measured voltage ratio is slightly below the turns ratio. The AC range of a multimeter measures RMS voltage, and the turns-ratio relationship applies to both step-up and step-down transformers."),
  ])

T("power_transmission", "Energy", "application",
  "For long-distance transmission, power is P = UI. Power lost to resistance R in the transmission lines is P_loss = I²R. At fixed power, increasing the transmission voltage reduces the current and is an effective way to reduce losses. Understand the roles of step-up and step-down transformers in power transmission.",
  ["Use I = P/U and P_loss = I²R to calculate transmission losses", "Explain why high-voltage transmission is used", "Describe the roles of step-up and step-down transformers in transmission lines"],
  [("S2.2.5", "exact")],
  pre=[("transformer", "hard"), ("joule", "hard"), ("electric_work", "soft")],
  qs=[
    N("basic", "A power station supplies P = 100 kW of power at a transmission voltage of U = 10 kV. What is the current in the transmission line in A? (Enter a number only.)", "10",
      "I = P/U = 100×10³ W ÷ 10×10³ V = 10 A.",
      "round(100e3/10e3,6)"),
    C("basic", "Why is high-voltage transmission used for long-distance power transmission?",
      "For a fixed transmitted power, higher voltage means lower current and less power lost in the lines",
      ["Higher voltage lowers the resistance of the transmission lines, reducing power loss", "Higher voltage increases the generator's output power, giving users more electrical energy", "Higher voltage increases the current, making power travel faster and reducing line losses"],
      "Transmission-line resistance depends on the wire material and dimensions, not on the voltage. Since P = UI, a higher U means a lower I for fixed P, reducing losses P_loss = I²R."),
    N("standard", "Electrical power P = 200 kW is transmitted at U = 20 kV through lines with a total resistance R = 10 Ω. Find the power lost in the lines in W. (Enter a number only.)",
      "1000",
      "I = P/U = 200×10³ ÷ 20×10³ = 10 A, so P_loss = I²R = 10² × 10 = 1000 W. Using U²/R gives 4×10⁷ W, incorrectly treating the transmission voltage as the voltage drop across the lines.",
      "round((200e3/20e3)**2*10,6)"),
    C("advanced", "If the transmitted power and line resistance stay constant while the transmission voltage increases tenfold, by what factor does the power lost in the lines change?",
      "1/100", ["1/10", "10 times", "100 times"],
      "I = P/U, so increasing U tenfold reduces I to one-tenth. Since P_loss = I²R, the power loss becomes 1/100 of its original value. Using P_loss = U²/R by mistake gives 100 times the loss; considering only that I falls to one-tenth leads to 1/10."),
  ])

T("generator_motor", "Energy", "conceptual",
  "A generator converts mechanical energy into electrical energy; a motor converts electrical energy into mechanical energy and internal energy. As a motor turns, its coil cuts magnetic field lines and generates a back emf that opposes the current. Input power UI equals the sum of mechanical power and the coil's heating power I²r.",
  ["Describe energy conversions in generators and motors", "Explain the role of back emf", "Calculate a motor's mechanical power and analyze a stalled motor"],
  [("S2.2.6", "exact")],
  pre=[("ac_generate", "hard"), ("ampere_force", "hard"), ("lenz", "soft"), ("electric_work", "soft"), ("J:motor", "soft")],
  qs=[
    C("basic", "What energy conversion occurs in a generator?", "Mechanical energy is converted into electrical energy", ["Electrical energy is converted into mechanical energy", "Chemical energy is converted into electrical energy", "Internal energy is converted into mechanical energy"],
      "An external force drives the generator's coil to rotate. As the coil cuts magnetic field lines, it produces an induced emf and converts mechanical energy into electrical energy. A motor converts electrical energy into mechanical energy."),
    C("basic", "When a motor is rotating normally, its coil cuts magnetic field lines and generates a back emf. How does this affect the current in the circuit?",
      "It opposes the current, making it less than U/r",
      ["It assists the current, increasing it", "It has no effect; the current always equals U/r", "It is in the same direction as the source emf, so the two currents add"],
      "By Lenz's law, the back emf is opposite to the source voltage and opposes the current. Therefore, while the motor is turning, I is less than U/r, where r is the coil resistance. Treating the motor as a pure resistor gives an overestimate of the current."),
    N("standard", "A motor has coil resistance r = 4 Ω and is connected to a U = 220 V supply. During normal operation, its current is I = 5 A. Find its mechanical output power in W. (Enter a number only.)",
      "1000",
      "Input power is UI = 220 × 5 = 1100 W; coil heating power is I²r = 25 × 4 = 100 W. Mechanical power = 1100 - 100 = 1000 W. Calculating with U²/r would be entirely incorrect.",
      "round(220*5-5**2*4,6)"),
    N("standard", "A motor with coil resistance r = 4 Ω is connected to a U = 220 V supply. If the rotor is jammed and cannot turn, what is the current in A? (Enter a number only.)",
      "55",
      "When stalled, the motor does not rotate and produces no back emf, so it acts as a pure resistor. I = U/r = 220/4 = 55 A, far greater than the normal operating current of 5 A; the coil will quickly overheat and burn out.",
      "round(220/4,6)"),
  ])

# ---------------- Selective Compulsory Volume 2, Chapter 4: Electromagnetic Oscillations and Waves
T("lc_oscillation", "Motion and Interaction", "reasoning",
  "In an LC circuit, the capacitor repeatedly charges and discharges, causing the current and charge to vary periodically. Electric-field energy and magnetic-field energy convert into each other, while total energy remains constant if losses are ignored. The oscillation period is T = 2π√(LC), and the frequency is f = 1/(2π√(LC)).",
  ["Analyze changes in current, charge, and energy as an LC circuit charges and discharges", "Use T = 2π√(LC) to calculate period and frequency", "Determine how the period changes when L or C changes"],
  [("S2.3.2", "exact")],
  pre=[("capacitor", "hard"), ("self_inductance", "hard"), ("exp_capacitor", "soft")],
  qs=[
    C("basic", "In an LC oscillator, what is true at the instant the capacitor has finished discharging (the charge on its plates is zero)?",
      "Current and magnetic-field energy are maximum, and electric-field energy is zero",
      ["Current and magnetic-field energy are zero, and electric-field energy is maximum", "Current is maximum, magnetic-field energy is zero, and electric-field energy is maximum", "Current is zero, magnetic-field energy is maximum, and electric-field energy is zero"],
      "When the charge is zero, electric-field energy is zero. All the energy has become magnetic-field energy in the coil, and the current is maximum. When the capacitor's charge is maximum, the current and magnetic-field energy are zero."),
    N("basic", "In an LC oscillator, the coil's inductance is L = 2.5 mH and the capacitor's capacitance is C = 1 μF. What is the oscillation period T in μs? (Use π = 3.14; enter a number only.)",
      "314",
      "T = 2π√(LC) = 2 × 3.14 × √(2.5×10⁻³ × 1×10⁻⁶) = 2 × 3.14 × 5×10⁻⁵ s = 3.14×10⁻⁴ s = 314 μs. Omitting 2π gives 50 μs.",
      "round(2*3.14*sqrt(2.5e-3*1e-6)*1e6,4)"),
    C("standard", "In an LC oscillator, the capacitor is charging. Which statement is correct?",
      "Current decreases as magnetic-field energy converts into electric-field energy",
      ["Current increases as magnetic-field energy converts into electric-field energy", "Current decreases as electric-field energy converts into magnetic-field energy", "The charge on the capacitor plates decreases"],
      "During charging, the charge on the plates and the electric-field energy increase, while magnetic-field energy and current decrease. During discharging, electric-field energy converts into magnetic-field energy and the current increases."),
    C("advanced", "In an LC oscillator, the coil's inductance is increased by a factor of 4 while the capacitance is reduced to one-fourth. By what factor does the oscillation period change?",
      "It is unchanged", ["4", "1/4", "2"],
      "Since T = 2π√(LC), the product LC is unchanged and so is the period. Considering only the increase in L leads to the incorrect answer 2 (√4); considering only the decrease in C leads to 1/2."),
  ])

T("maxwell", "Motion and Interaction", "conceptual",
  "Maxwell's electromagnetic field theory: a changing magnetic field produces an electric field, and a changing electric field produces a magnetic field. A uniformly changing field produces a constant field; a periodically changing field produces a periodic field of the same frequency. Changing electromagnetic fields propagate outward as electromagnetic waves. These are transverse waves and travel at speed c in a vacuum, independent of frequency.",
  ["State Maxwell's two basic propositions and identify the type of field produced", "Know that electromagnetic waves are transverse, with E, B, and the direction of propagation mutually perpendicular", "Use c = λf to calculate wavelength and frequency"],
  [("S2.3.1", "exact"), ("S2.3.3", "inferred")],
  pre=[("faraday", "hard"), ("em_wave", "hard"), ("lc_oscillation", "soft"), ("ampere_rule", "soft"), ("wave_params", "soft"), ("J:em_wave", "soft")],
  qs=[
    C("basic", "What is a basic proposition of Maxwell's electromagnetic field theory?",
      "A changing magnetic field produces an electric field, and a changing electric field produces a magnetic field",
      ["A constant magnetic field produces an electric field, and a constant electric field produces a magnetic field", "A changing magnetic field produces a magnetic field, and a changing electric field produces an electric field", "Only a changing magnetic field can produce an electric field; an electric field cannot produce a magnetic field"],
      "Faraday discovered that a changing magnetic field produces an electric field. Maxwell further proposed that a changing electric field can also produce a magnetic field. Constant fields do not produce new fields."),
    C("basic", "The magnetic flux density increases uniformly in a region of space. What kind of electric field is produced in that region?",
      "A constant electric field", ["A uniformly changing electric field", "A periodically changing electric field", "No electric field"],
      "A uniformly changing magnetic field produces a constant electric field. A nonuniformly changing magnetic field, such as an oscillating one, produces a changing electric field. For a uniform change in B, its rate of change is constant, so the resulting E does not vary with time."),
    N("standard", "A radio station broadcasts an electromagnetic wave at 600 kHz. What is its wavelength in a vacuum in m? (c = 3×10⁸ m/s; enter a number only.)",
      "500",
      "λ = c/f = 3×10⁸ ÷ (600×10³) = 500 m. Convert the frequency from kHz to Hz; otherwise, an incorrect result such as 0.5 m is obtained.",
      "round(3e8/600e3,6)"),
    C("standard", "Which statement about electromagnetic waves is correct?",
      "They are transverse waves, and their speed in a vacuum is independent of frequency",
      ["They need a medium to propagate and cannot travel through a vacuum", "They are longitudinal waves, with the electric field parallel to the direction of propagation", "Higher-frequency electromagnetic waves travel faster in a vacuum"],
      "In an electromagnetic wave, E and B are perpendicular to each other and to the direction of propagation, so the wave is transverse. Electromagnetic waves need no medium; all travel at speed c in a vacuum, independent of frequency. Their speed can depend on frequency in a medium."),
  ])

T("radio", "Motion and Interaction", "conceptual",
  "Radio transmission requires a high-frequency, open LC oscillator. Modulation places signals such as audio on a high-frequency carrier: amplitude modulation changes the amplitude, while frequency modulation changes the frequency. At the receiver, tuning selects a station, and demodulation (detection) extracts the signal.",
  ["Describe the conditions needed for effective electromagnetic-wave transmission", "Distinguish modulation, tuning, and demodulation", "Use f = 1/(2π√(LC)) to analyze how L and C affect the resonant frequency of a tuning circuit"],
  [("S2.3.3", "exact")],
  pre=[("lc_oscillation", "hard"), ("maxwell", "hard"), ("J:broadcast", "soft")],
  qs=[
    C("basic", "What condition should an LC oscillator satisfy to transmit electromagnetic waves effectively?",
      "It should oscillate at a sufficiently high frequency and be an open circuit",
      ["It should oscillate at a sufficiently low frequency and be a closed circuit", "It should oscillate at a sufficiently low frequency and be an open circuit", "It should oscillate at a sufficiently high frequency and be a closed circuit"],
      "Higher frequencies radiate electromagnetic waves more effectively. The circuit must be open so that the electric and magnetic fields spread over a larger region. In a closed LC circuit, the fields are concentrated in the capacitor and coil, making transmission difficult."),
    C("basic", "A radio dial changes the capacitance of a variable capacitor until the receiver's natural frequency matches the frequency broadcast by a station, selecting that station. What is this process called?",
      "Tuning", ["Modulation", "Demodulation", "Frequency modulation"],
      "Tuning is the process by which a receiver resonates electrically to select the desired station. Adding a signal to a carrier is modulation; extracting the signal from the received high-frequency current is demodulation (detection)."),
    N("standard", "A radio's tuning circuit has a fixed coil inductance L and receives a station at frequency f when its capacitance is 200 pF. What capacitance is needed to receive a station at frequency 2f? (Enter a number only.)",
      "50",
      "f = 1/(2π√(LC)), so f is inversely proportional to √C. Doubling f requires reducing C to one-fourth: C = 200/4 = 50 pF. Dividing by 2 instead gives 100 pF.",
      "round(200/2**2,6)"),
    C("standard", "Which statement about an amplitude-modulated (AM) radio wave is correct?",
      "The carrier's amplitude varies with the audio signal, while its frequency remains constant",
      ["The carrier's frequency varies with the audio signal, while its amplitude remains constant", "The carrier's propagation speed varies with the audio signal", "Neither the carrier's amplitude nor its frequency changes"],
      "Amplitude modulation varies the high-frequency carrier's amplitude with the signal; frequency modulation (FM) varies its frequency. Modulation does not change the speed of an electromagnetic wave in a vacuum, which remains c."),
  ])

T("em_spectrum", "Motion and Interaction", "conceptual",
  "In order of decreasing wavelength, the electromagnetic spectrum is radio waves, infrared, visible light, ultraviolet, X-rays, and gamma rays. They all travel at the same speed in a vacuum; higher frequency means shorter wavelength. Each band has distinct properties and applications.",
  ["List the electromagnetic spectrum in order of wavelength", "Match common applications to the corresponding wave bands", "Use c = λf to convert between wavelength and frequency in a vacuum"],
  [("S2.3.4", "exact")],
  pre=[("maxwell", "hard"), ("em_wave", "soft"), ("J:dispersion", "soft")],
  qs=[
    C("basic", "Which sequence correctly orders electromagnetic waves from longest to shortest wavelength?",
      "Radio waves, infrared, visible light, ultraviolet, X-rays, gamma rays",
      ["Radio waves, infrared, visible light, X-rays, ultraviolet, gamma rays",
       "Radio waves, ultraviolet, visible light, infrared, X-rays, gamma rays",
       "Gamma rays, X-rays, ultraviolet, visible light, infrared, radio waves"],
      "From longest to shortest wavelength: radio waves > infrared > visible light > ultraviolet > X-rays > gamma rays. Reversing the sequence gives shortest to longest; switching ultraviolet and X-rays is a common mistake."),
    C("basic", "Which technology is correctly matched with the electromagnetic wave it uses?",
      "A television remote control — infrared",
      ["A banknote detector identifying fluorescent marks — X-rays", "A germicidal lamp — infrared", "Chest radiography — ultraviolet"],
      "Remote controls emit infrared. Banknote detectors use ultraviolet to make fluorescent materials glow; germicidal lamps also use ultraviolet; chest radiography uses highly penetrating X-rays."),
    N("standard", "What is the wavelength in nm of ultraviolet light with frequency 1.5×10¹⁵ Hz in a vacuum? (c = 3×10⁸ m/s; 1 nm = 10⁻⁹ m; enter a number only.)",
      "200",
      "λ = c/f = 3×10⁸ ÷ 1.5×10¹⁵ = 2×10⁻⁷ m = 200 nm. Forgetting to convert m to nm gives 2×10⁻⁷.",
      "round(3e8/1.5e15*1e9,6)"),
    C("standard", "Which statement about infrared radiation is correct?",
      "All objects continuously emit infrared radiation, and hotter objects emit more strongly",
      ["Only objects above 100 °C emit infrared radiation; cooler objects emit none", "Infrared is visible red light, which is why it is called infrared", "Infrared penetrates more strongly than X-rays and is commonly used for chest radiography"],
      "Every object above absolute zero emits infrared radiation; thermal cameras work on this principle. Infrared is invisible to the human eye and is much less penetrating than X-rays."),
  ])

# ---------------- Selective Compulsory Volume 2, Chapter 5: Sensors
T("sensor_intro", "Interdisciplinary Practice", "conceptual",
  "A sensor converts nonelectrical quantities such as force, heat, light, sound, and displacement into electrical quantities that are easy to measure and transmit, such as voltage, current, resistance, or capacitance. It usually contains a sensing element and a conversion element. Learn the meaning and types of sensors.",
  ["Describe the role and basic components of a sensor", "Relate common nonelectrical quantities to their corresponding electrical quantities", "Analyze simple sensor circuits using closed-circuit principles"],
  [("S2.4.1", "exact"), ("S2.4.3", "inferred")],
  pre=[("resistance", "hard"), ("ohm_law", "hard"), ("series_parallel", "soft"), ("closed_circuit", "soft")],
  qs=[
    C("basic", "What is the role of a sensor?",
      "To convert a nonelectrical quantity into an electrical quantity that is easy to measure and transmit",
      ["To convert an electrical quantity into a nonelectrical one such as force, heat, or light", "To amplify a weak electrical signal into a strong signal that is easy to transmit", "To store electrical energy and continuously supply it to an appliance"],
      "A sensor's main role is to convert quantities such as force, heat, and light into electrical quantities such as voltage, current, and resistance for measurement, transmission, and control."),
    C("basic", "Which device is a sensor that converts a mechanical quantity into an electrical quantity?",
      "The strain gauge in an electronic scale",
      ["The photoresistor in an automatic streetlight circuit", "The temperature-sensitive magnetic element in a rice cooker", "The infrared detector in an infrared alarm"],
      "When force deforms the strain gauge in an electronic scale, its resistance changes, converting force → resistance. A photoresistor senses light, the magnetic element senses temperature, and the infrared detector senses infrared radiation."),
    N("standard", "A simple electronic scale has an ideal 6 V source, a fixed resistor R0 = 10 Ω, and a force-sensitive resistor R in series. Its resistance depends on force F as R = 30 - 0.5F, where R is in Ω and F is in N, with 0 ≤ F ≤ 60. What is the circuit current in A when F = 20 N? (Enter a number only.)",
      "0.2",
      "At F = 20 N, R = 30 - 10 = 20 Ω. The total resistance is 10 + 20 = 30 Ω, so I = 6/30 = 0.2 A.",
      "round(6/(10+30-0.5*20),6)"),
    N("standard", "A simple electronic scale has an ideal 6 V source, a fixed resistor R0 = 10 Ω, and a force-sensitive resistor R in series, with R = 30 - 0.5F (R in Ω, F in N). If the ammeter reads 0.3 A, what force F acts on the force-sensitive resistor in N? (Enter a number only.)",
      "40",
      "The total resistance is 6/0.3 = 20 Ω, so R = 20 - 10 = 10 Ω. From 10 = 30 - 0.5F, F = 40 N. A larger current means a smaller R and therefore a greater force.",
      "round((30-(6/0.3-10))/0.5,6)"),
  ])

T("sensor_types", "Interdisciplinary Practice", "application",
  "Common sensors include photoresistors (resistance decreases as illumination increases), thermistors (NTC resistance decreases as temperature rises), metal resistance thermometers (resistance increases as temperature rises), Hall elements (convert magnetic flux density into voltage), and pressure, sound, and infrared sensors. Learn their operating principles and applications.",
  ["State how photoresistor and thermistor resistance changes with conditions", "Explain how a Hall element converts magnetic flux density into voltage", "Match common sensors with practical applications"],
  [("S2.4.2", "exact"), ("S2.4.3", "exact")],
  pre=[("sensor_intro", "hard"), ("lorentz_force", "hard"), ("resistance", "soft")],
  qs=[
    C("basic", "How does the resistance of a photoresistor vary with illumination?",
      "Its resistance decreases as illumination increases",
      ["Its resistance increases as illumination increases", "It has resistance only above a certain illumination level", "Its resistance is independent of illumination and varies only with temperature"],
      "A photoresistor is made of semiconductor material. Light increases the number of charge carriers and improves conductivity, reducing its resistance."),
    C("basic", "As temperature rises, how do the resistances of a metal resistance thermometer and an NTC thermistor change?",
      "The metal resistance increases, while the NTC thermistor resistance decreases",
      ["Both resistances increase", "Both resistances decrease", "The metal resistance decreases, while the NTC thermistor resistance increases"],
      "The resistivity of a metal increases with temperature. An NTC thermistor is made of semiconductor material; as its temperature rises, the number of charge carriers increases and its resistance decreases significantly."),
    C("standard", "Which component is correctly matched with its application?",
      "A Hall element — converts magnetic flux density into voltage and can be used to measure a magnetic field",
      ["A photoresistor — converts temperature changes into resistance changes for temperature measurement", "A thermistor — converts illumination into resistance changes to detect light", "A strain gauge — converts temperature into voltage to measure temperature"],
      "A Hall element produces a Hall voltage U proportional to B in a magnetic field, so it can measure magnetic flux density. A photoresistor responds to light, and a thermistor responds to temperature."),
    N("advanced", "A Hall element is placed in a uniform magnetic field with B = 0.5 T, perpendicular to its upper and lower surfaces. Charge carriers in the element drift along the current at v = 0.1 m/s. The element is d = 2 mm wide in the direction perpendicular to both the field and the current. What is the steady Hall voltage U in mV? (Enter a number only.)",
      "0.1",
      "At equilibrium, the electric force balances the Lorentz force: qU/d = qvB, so U = Bvd = 0.5 × 0.1 × 0.002 = 1×10⁻⁴ V = 0.1 mV. Watch the unit conversion: 1 V = 1000 mV.",
      "round(0.5*0.002*0.1*1000,6)"),
  ])

T("exp_sensor", "Interdisciplinary Practice", "procedural",
  "Use a photoresistor or thermistor, an electromagnetic relay, and a power source to assemble a light- or temperature-controlled device, such as a streetlight that switches on automatically at dusk. Learn how to connect sensors, how relays work, and how to adjust sensitivity.",
  ["Draw a basic circuit for a light- or temperature-controlled device", "Know that an electromagnetic relay uses a low-power circuit to control a high-power circuit", "Adjust the trigger threshold by changing a resistor"],
  [("S2.X.3", "exact"), ("S2.4.2", "inferred")],
  pre=[("sensor_types", "hard"), ("closed_circuit", "hard"), ("J:electromagnet", "soft")],
  qs=[
    C("basic", "In a light-controlled circuit, a photoresistor RG and fixed resistor R0 are connected in series across a constant-voltage source. As it gets darker, RG increases. How does the voltage across R0 change?",
      "It decreases", ["It increases", "It remains unchanged", "It first increases, then decreases"],
      "The series current is I = U/(RG + R0). As RG increases, I decreases, so the voltage across R0, U0 = IR0, decreases."),
    C("basic", "What is the main role of an electromagnetic relay in a light-controlled streetlight?",
      "A low-power control circuit switches a high-power working circuit on or off",
      ["It converts AC to DC for the control circuit", "It amplifies the photoresistor's resistance to make the control more sensitive", "It supplies backup power to keep the streetlight on during an outage"],
      "When energized, the relay's electromagnet pulls in the armature to open or close the working circuit. This lets a low-power circuit control a high-power circuit while keeping the two circuits electrically isolated."),
    N("standard", "A light-controlled circuit has a 6 V source and a fixed resistor R0 = 20 Ω in series with a photoresistor RG. The relay activates when the voltage across R0 falls to 2 V. What is the photoresistor's resistance RG in Ω? (Enter a number only.)",
      "40",
      "I = U0/R0 = 2/20 = 0.1 A. The voltage across RG is 6 - 2 = 4 V, so RG = 4/0.1 = 40 Ω.",
      "round((6-2)/(2/20),6)"),
    C("advanced", "In a light-controlled circuit, a fixed resistor R0 and a photoresistor are connected in series across a constant-voltage source. A relay switches on the streetlight when the voltage across R0 falls below a set value. Which change makes the light switch on only when it is darker?",
      "Increase the resistance of R0",
      ["Decrease the resistance of R0", "Decrease the source voltage", "Connect a resistor in parallel with R0"],
      "The trigger occurs when U0 = U·R0/(R0 + RG) falls to the set value, so RG = R0(U/U_set - 1). A larger R0 requires a larger RG, corresponding to lower illumination, so the light switches on when it is darker. Decreasing R0, decreasing U, or adding a parallel resistor (which effectively decreases R0) makes the light switch on when it is brighter."),
  ])

# ---------------- Selective Compulsory Volume 3, Chapter 1: Kinetic Theory of Molecules
T("molecular_basic", "Matter", "conceptual",
  "The kinetic theory of molecules: matter consists of a large number of molecules; molecular diameters are on the order of 10⁻¹⁰ m; Avogadro's constant is N_A = 6.02×10²³ mol⁻¹; molecules are in continuous random motion; and intermolecular forces include both attraction and repulsion, which are equal at r0.",
  ["Know the order of magnitude of molecular size and the value of Avogadro's constant", "Use molar mass and N_A to calculate the number and volume of molecules", "Describe how intermolecular forces vary with separation"],
  [("S3.1.1", "exact")],
  pre=[("J:molecule", "hard"), ("J:internal", "soft")],
  math=[("cnm_164", "Molecular sizes and Avogadro's constant are expressed using scientific notation and negative integer exponents.")],
  qs=[
    C("basic", "What is the order of magnitude of a molecular diameter?",
      "10⁻¹⁰ m", ["10⁻⁸ m", "10⁻¹⁵ m", "10⁻⁶ m"],
      "The diameter of a typical molecule is on the order of 10⁻¹⁰ m. An atomic nucleus is about 10⁻¹⁵ m across, while 10⁻⁶ m is on the micrometer scale."),
    N("basic", "The molar mass of water is 18 g/mol, and Avogadro's constant is N_A = 6.02×10²³ mol⁻¹. How many molecules are in 27 g of water? (Enter the number in units of 10²³; enter a number only.)",
      "9.03",
      "n = 27/18 = 1.5 mol, so N = nN_A = 1.5 × 6.02×10²³ = 9.03×10²³ molecules.",
      "round(27/18*6.02,4)"),
    C("standard", "When the separation r between two molecules is greater than the equilibrium separation r0 (but no more than 10r0), which statement is correct?",
      "Attraction and repulsion both act; attraction is stronger, so the net intermolecular force is attractive",
      ["Only attraction acts; there is no repulsion, so the net intermolecular force is attractive", "Repulsion is stronger than attraction, so the molecules tend to move apart", "Both attraction and repulsion disappear, so there is no force or interaction between the molecules"],
      "Intermolecular attraction and repulsion both act and decrease as separation increases, but repulsion decreases more rapidly. For r > r0, attraction is stronger and the net force is attractive; for r < r0, repulsion dominates; at r = r0, the net force is zero; beyond 10r0, the forces can be neglected."),
    N("standard", "The molar mass of water is 18 g/mol, its density is 1.0 g/cm³, and Avogadro's constant is 6.0×10²³ mol⁻¹. What is the approximate volume of one water molecule? (Enter the value in units of 10⁻²⁹ m³; enter a number only.)",
      "3",
      "The volume of one water molecule is V0 = M/(ρN_A) = 18 ÷ (1.0 × 6.0×10²³) cm³ = 3.0×10⁻²³ cm³ = 3.0×10⁻²⁹ m³, using 1 cm³ = 10⁻⁶ m³.",
      "round(18/1.0/6.0e23*1e-6/1e-29,4)"),
  ])

T("brownian", "Matter", "conceptual",
  "Brownian motion is the random motion of small solid particles suspended in a liquid. It is not the motion of the molecules themselves, but evidence of the random motion of liquid molecules. Brownian motion is more pronounced for smaller particles and at higher temperatures. Diffusion, in which substances interpenetrate, also shows that molecules are in motion.",
  ["Explain what Brownian motion is and is not", "Explain the cause of Brownian motion and the factors that affect it", "Distinguish Brownian motion from diffusion"],
  [("S3.1.2", "exact")],
  pre=[("molecular_basic", "hard"), ("J:molecule", "soft")],
  qs=[
    C("basic", "What does Brownian motion refer to?",
      "The random motion of small solid particles suspended in a liquid",
      ["The random motion of liquid molecules", "The random motion of molecules inside a small solid particle", "The rising motion of bubbles in a liquid"],
      "Brownian motion is the visible motion of small solid particles, each composed of many molecules; it is not the motion of individual molecules. It indirectly demonstrates that liquid molecules move randomly."),
    C("basic", "Pollen grains are observed under a microscope in water. Under which conditions is their Brownian motion most pronounced?",
      "Higher water temperature and smaller pollen particles",
      ["Lower water temperature and smaller pollen particles", "Higher water temperature and larger pollen particles", "Lower water temperature and larger pollen particles"],
      "At higher temperatures, liquid molecules move more vigorously. Smaller particles experience a greater imbalance in molecular impacts from different directions, so their Brownian motion is more pronounced."),
    C("standard", "Which of the following is an example of diffusion?",
      "Sugar is added to hot water, and the whole glass of water gradually becomes sweet",
      ["Dust is seen swirling in the air in sunlight", "Pollen grains are seen jiggling under a microscope", "Wind blows sand and dust across the ground"],
      "Diffusion is the interpenetration of different substances caused by molecular motion. Dust swirling and sand blowing are caused by air currents; pollen jiggling is Brownian motion. Neither is diffusion."),
    C("advanced", "Why is Brownian motion more pronounced for smaller suspended particles?",
      "Molecular impacts from different directions are more unbalanced for smaller particles, demonstrating that liquid molecules move randomly",
      ["Smaller particles are at a higher temperature, so they move more vigorously", "Smaller particles have less weight, so buoyancy makes them move continually up and down", "Molecules inside smaller particles move more vigorously, causing the whole particle to move more vigorously"],
      "Liquid molecules strike a particle randomly from all directions. For a smaller particle, the net imbalance in these impacts is greater, and its lower mass makes its motion easier to change. The particle is at the same temperature as the liquid; molecular motion inside it is distinct from Brownian motion."),
  ])

T("exp_oil_film", "Matter", "procedural",
  "Estimate molecular diameter using the oil-film method: dilute oleic acid with alcohol, then drop it onto water sprinkled with talcum powder to form a monomolecular film. Estimate the molecular diameter with d = V/S, where V is the pure oleic acid volume in one drop of solution and S is the film area. Practice volume conversion, estimating area by counting grid squares, and analyzing error.",
  ["Explain the purposes of diluting oleic acid and sprinkling talcum powder", "Calculate the pure oleic acid volume in one drop of solution and the area of the oil film", "Use d = V/S to estimate molecular diameter and analyze error"],
  [("S3.X.1", "exact"), ("S3.1.1", "inferred")],
  pre=[("molecular_basic", "hard"), ("exp_length", "soft")],
  math=[("cnm_164", "Unit conversions for volume and area, and the final result, require scientific notation and negative exponents.")],
  qs=[
    C("basic", "When using the oil-film method to estimate molecular diameter, why is oleic acid first diluted with alcohol?",
      "To help form a monomolecular film and calculate the pure oleic acid volume in one drop of solution",
      ["To make oleic acid molecules smaller so their diameter is easier to measure", "To form a multilayer film that is thicker and easier to measure", "To speed up the reaction between oleic acid and water so the film stabilizes sooner"],
      "Pure oleic acid is viscous, and a drop has too much volume to spread easily into a single molecular layer. After dilution, a drop contains a small volume of pure oleic acid that can spread into a monolayer. Alcohol evaporates or dissolves in the water without affecting the film area, and the mixture ratio and drop count can be used to calculate the pure oleic acid volume in each drop."),
    N("basic", "A solution is made by diluting 1 mL of pure oleic acid to 500 mL with alcohol. A measured 1 mL sample contains 80 drops. What volume of pure oleic acid is in each drop? (Enter the value in units of 10⁻⁶ mL; enter a number only.)",
      "25",
      "Each drop has a solution volume of 1/80 mL, and pure oleic acid makes up 1/500 of the solution. Thus each drop contains V = 1/(500 × 80) mL = 2.5×10⁻⁵ mL = 25×10⁻⁶ mL of pure oleic acid.",
      "round(1/500/80*1e6,6)"),
    N("standard", "A drop of oleic acid-alcohol solution contains 2.5×10⁻⁵ mL (2.5×10⁻⁵ cm³) of pure oleic acid. It forms a monomolecular film on water covering 250 grid squares, each with area 1 cm². Estimate the diameter of an oleic acid molecule. (Enter the value in units of 10⁻¹⁰ m; enter a number only.)",
      "10",
      "d = V/S = 2.5×10⁻⁵ cm³ ÷ 250 cm² = 1×10⁻⁷ cm = 1×10⁻⁹ m = 10×10⁻¹⁰ m. Keep volume and area units consistent; failing to convert between cm and m causes a factor-of-100 error.",
      "round(2.5e-5/250*1e-2/1e-10,4)"),
    C("advanced", "Which procedure would make the molecular diameter measured by the oil-film method too large?",
      "Sprinkle too much talcum powder on the water and trace the film before it has fully spread",
      ["Count every grid square smaller than half a square as a full square when calculating the film area",
       "Overcount the number of drops when measuring the solution volume",
       "Let the oleic acid-alcohol solution stand until alcohol evaporates and its concentration rises, but continue using the original concentration"],
      "Since d = V/S, a film that has not fully spread has too small an area S and gives a diameter that is too large. Counting squares smaller than half a square as full squares makes S too large and d too small. Overcounting drops makes the volume V per drop too small and d too small. Alcohol evaporation increases the actual concentration, so using the original concentration underestimates V and d."),
  ])

T("speed_distribution", "Matter", "conceptual",
  "The speeds of large numbers of gas molecules follow a statistical distribution: few molecules have very high or very low speeds, while most have intermediate speeds. As temperature rises, the peak of the speed-distribution curve shifts toward higher speeds and the curve flattens, but not every molecule speeds up.",
  ["Describe the molecular speed distribution as 'many in the middle, few at either end'", "Compare speed-distribution curves at different temperatures", "Interpret statistical graphs of molecular speeds and perform simple calculations"],
  [("S3.1.2", "exact")],
  pre=[("molecular_basic", "hard"), ("brownian", "soft"), ("J:temperature", "soft")],
  qs=[
    C("basic", "At a fixed temperature, what is the speed distribution of gas molecules?",
      "There are few molecules with very high or very low speeds and most have intermediate speeds",
      ["All molecules have the same speed, equal to the average speed", "The number of molecules increases with speed, so the distribution curve rises monotonically", "The number of molecules increases as speed decreases, so the distribution curve falls monotonically"],
      "The speed distribution of a large number of molecules has many in the middle and few at either end. Molecules do not all have the same speed, nor are there more molecules at either the highest or lowest speeds."),
    C("basic", "For the same gas, the temperature rises from T1 to T2. How does the molecular speed-distribution curve change?",
      "Its peak shifts toward higher speeds, and the curve becomes flatter",
      ["Its peak shifts toward lower speeds, and the curve becomes sharper", "The peak stays in the same place, and the entire curve rises", "The fraction of molecules in every speed interval increases"],
      "As temperature rises, average molecular kinetic energy increases and the fraction of high-speed molecules grows, shifting the peak to the right. The total area under the curve, representing the total fraction, remains 1, so the peak falls and the curve flattens. The fraction in every interval cannot increase at once because the total stays constant."),
    C("standard", "For the same gas at temperatures T1 and T2, with T1 < T2, how do the areas under the molecular speed-distribution curves compare?",
      "They are equal; each represents 100% of the molecules", ["The area for T2 is larger", "The area for T1 is larger", "The areas cannot be compared"],
      "The vertical axis gives the percentage of molecules in each speed interval. The percentages sum to 100%, so the total area under the curve is the same at both temperatures."),
    N("standard", "At a certain temperature, oxygen molecule speeds are divided into five intervals. The percentages of molecules in the intervals are 12%, 22%, 31%, x, and 9%. Find x. (Enter a number without the percent sign.)",
      "26",
      "The percentages for all intervals sum to 100%, so x = 100 - 12 - 22 - 31 - 9 = 26, or 26%.",
      "100-12-22-31-9", percent=True),
  ])

T("molecular_ke", "Energy", "conceptual",
  "The average kinetic energy of molecular thermal motion indicates temperature: the higher the temperature, the greater the average molecular kinetic energy. Thermodynamic temperature is T = t + 273 K, and average kinetic energy is proportional to T. Temperature is not defined for a single molecule; at the same temperature, different gases have the same average molecular kinetic energy but different average speeds.",
  ["Explain how temperature indicates average molecular kinetic energy", "Distinguish average kinetic energy, average speed, and total kinetic energy", "Compare average molecular kinetic energies using thermodynamic temperature"],
  [("S3.1.1", "inferred"), ("S3.1.6", "inferred")],
  pre=[("speed_distribution", "hard"), ("kinetic_energy", "hard"), ("J:temperature", "soft")],
  qs=[
    C("basic", "Which statement about temperature and molecular kinetic energy is correct?",
      "Temperature indicates the average kinetic energy of molecular thermal motion",
      ["As temperature rises, the kinetic energy of every molecule increases", "At the same temperature, hydrogen and oxygen molecules have the same average speed", "Molecular thermal motion stops at 0 °C"],
      "As temperature rises, the average kinetic energy of a large number of molecules increases, though an individual molecule's kinetic energy may decrease. At the same temperature, average kinetic energies are equal; lighter molecules have higher average speeds. Molecules are always in motion, including at 0 °C."),
    C("basic", "At the same temperature, which statement about hydrogen and oxygen gases is correct?",
      "Their molecules have the same average kinetic energy, but hydrogen molecules have a higher average speed",
      ["Their molecules have the same average kinetic energy, but oxygen molecules have a higher average speed", "Hydrogen molecules have a higher average kinetic energy", "Oxygen molecules have a higher average kinetic energy"],
      "At the same temperature, molecular average kinetic energies are equal, so (1/2)m v² is the same. Hydrogen molecules have less mass, so their average speed is higher."),
    N("standard", "A fixed mass of gas is heated from 27 °C to 127 °C. By what factor does the average kinetic energy of its molecular thermal motion change? (Use T = t + 273 K; round to two decimal places; enter a number only.)",
      "1.33",
      "Average kinetic energy is proportional to thermodynamic temperature: (127 + 273)/(27 + 273) = 400/300 ≈ 1.33. Using the Celsius-temperature ratio 127/27 ≈ 4.7 is incorrect.",
      "round((127+273)/(27+273),2)"),
    C("standard", "Compare 10 g and 100 g of water, both at 0 °C. Which statement is correct?",
      "The molecules have the same average kinetic energy, but the 100 g sample has greater total molecular kinetic energy",
      ["The molecules in the 100 g sample have greater average kinetic energy", "The molecules in the 10 g sample have greater average kinetic energy", "The molecules have the same average kinetic energy and the same total kinetic energy in both samples"],
      "Average kinetic energy depends only on temperature, so it is the same at equal temperatures. The 100 g sample has more molecules and therefore greater total molecular kinetic energy."),
  ])

T("molecular_pe", "Energy", "reasoning",
  "Molecular potential energy depends on the relative positions of molecules. For r > r0, the net force is attractive and potential energy increases as r increases. For r < r0, the net force is repulsive and potential energy increases as r decreases. Molecular potential energy is minimal at r = r0. An object's internal energy is the sum of the kinetic and potential energies of all its molecules.",
  ["Determine changes in molecular potential energy from the work done by intermolecular forces", "Know that molecular potential energy is minimal at r0", "Analyze changes in molecular kinetic energy, potential energy, and internal energy during a change of state"],
  [("S3.1.1", "inferred"), ("S3.2.1", "inferred")],
  pre=[("molecular_basic", "hard"), ("molecular_ke", "hard"), ("work", "soft"), ("elastic_pe", "soft"), ("J:internal", "soft")],
  qs=[
    C("basic", "When the separation r between two molecules equals the equilibrium separation r0, which statement is correct?",
      "Molecular potential energy is at a minimum", ["Molecular potential energy is at a maximum", "The repulsive force between the molecules is zero", "The attractive force between the molecules is zero"],
      "At r = r0, attraction and repulsion are equal, so the net force is zero, but neither force is zero. Molecular potential energy is at a minimum."),
    C("basic", "As the separation r between two molecules decreases from above r0 to r0, how do the work done by the intermolecular force and the molecular potential energy change?",
      "The intermolecular force does positive work, and molecular potential energy decreases",
      ["The intermolecular force does negative work, and molecular potential energy increases", "The intermolecular force does positive work, and molecular potential energy increases", "The intermolecular force does negative work, and molecular potential energy decreases"],
      "For r > r0, the net intermolecular force is attractive. As the molecules move closer, force and displacement point in the same direction, so the force does positive work and potential energy decreases, as when gravity does positive work and gravitational potential energy falls."),
    C("standard", "As the separation r between two molecules increases from r0 to 10r0, how does their molecular potential energy change?",
      "It increases continuously", ["It decreases continuously", "It first decreases, then increases", "It first increases, then decreases"],
      "For r > r0, the net force is attractive. As r increases, the force does negative work, so molecular potential energy increases continuously and approaches its value at infinite separation."),
    C("advanced", "A 1 g sample of water at 0 °C freezes into ice at 0 °C and releases heat. Which statement about this process is correct?",
      "Internal energy decreases, average molecular kinetic energy is unchanged, and molecular potential energy decreases",
      ["Internal energy is unchanged because temperature is unchanged", "Internal energy decreases, average molecular kinetic energy decreases, and molecular potential energy is unchanged", "Internal energy and molecular potential energy both increase"],
      "The temperature stays constant, so average molecular kinetic energy is unchanged. Heat is released and internal energy decreases; the decrease must be in molecular potential energy, which falls as water molecules arrange themselves more regularly during freezing. Constant temperature does not mean constant internal energy."),
  ])
